from biwak.richtext.checklists import count


TEXTS = {
    "Todo": "notes",
    "Message": "content",
    "Doc": "content",
    "Upload": "description",
}


def count_existing(apps, schema_editor):
    """Counts the task lists of the texts saved so far"""
    for name, column in TEXTS.items():
        model = apps.get_model("items", name)
        for row in model.objects.filter(**{f"{column}__contains": "["}):
            done, total = count(getattr(row, column))
            if total:
                model.objects.filter(pk=row.pk).update(
                    checklist_done=done, checklist_total=total
                )


